  '· 令牌等于你 GitHub 账号的仓库读写权。设备丢失或外借时，请到 GitHub 的设置 → 应用授权里撤销 Anikumo 的授权，令牌立即失效。\n· 数据文件存在 GitHub 的服务器上。自动创建的仓库是私有的，但请不要把仓库改成公开，也不要把令牌发给任何人。\n· GitHub 在部分网络环境下连接不稳定，同步可能失败或很慢；失败不影响本机使用，数据都在本地，联网正常时再同步即可。\n· 两台设备交替使用时，请尽量在一台上同步完成后再换另一台，避免旧的那份盖掉新的。': '· トークンは GitHub アカウントのリポジトリ読み書き権限そのものです。端末を紛失したり貸したりした場合は、GitHub の設定 → 承認済みアプリで Anikumo の承認を取り消してください。トークンは即座に無効になります。\n· データファイルは GitHub のサーバー上にあります。自動作成されたリポジトリはプライベートですが、公開に変更したり、トークンを誰かに教えたりしないでください。\n· 一部のネットワーク環境では GitHub への接続が不安定で、同期が失敗したり遅くなったりする場合があります。失敗してもローカル利用には影響せず、データは端末に残ります。ネットワークが正常なときに再同期してください。\n· 2台の端末を交互に使う場合は、1台で同期を終えてからもう1台に切り替え、古いコピーが新しいものを上書きしないようにしてください。',
