  '与地址模板可用变量相同，合并进最终 URL 的查询参数。': 'アドレス テンプレートと同じ変数が使え、最終 URL のクエリパラメータにマージされます。',
  '与本地备份一致：动漫的收藏与观看历史、漫画与小说的收藏和阅读进度、部分设置与已安装的源配置。不包含：下载好的视频、漫画章节等文件本身（太大，也不适合放仓库）；影视区的收藏与历史暂时还没有纳入备份范围。另外 GitHub 接口对单个文件有约 1MB 的上限，数据量特别大时同步会提示失败，可以改用本地备份页导出文件手动保存。': 'ローカルバックアップと同じです：アニメのコレクションと視聴履歴、漫画と小説のお気に入りと読書進捗、一部の設定とインストール済みソース設定。含まれないもの：ダウンロード済みの動画や漫画チャプターのファイル自体（大きすぎてリポジトリ向きではありません）。映像エリアのお気に入りと履歴はまだ対象外です。また GitHub の API には1ファイル約1MBの上限があり、データ量が特に大きいと同期に失敗する場合があります。その場合はローカルバックアップページからファイルを書き出して手動で保存してください。',
