  '登录此源': 'このソースにログイン',
  '登录用的是 GitHub 的设备码方式：应用给你一串短码，你在浏览器打开 GitHub 输入这串码确认，应用就拿到一枚只属于你账号的令牌。全程不需要把 GitHub 密码告诉应用，应用里也不内置任何密钥。\n\n令牌只保存在这台设备的本地设置里。同步时，应用把一份和「本地备份」相同的数据文件（anikumo-backup.json）写到你选择或自动创建的仓库里；换设备时在新设备登录同一账号、选同一仓库，同步一次就能把数据恢复过来。': 'ログインには GitHub のデバイスコード方式を使います：アプリが短いコードを表示し、ブラウザで GitHub を開いてそのコードを入力して確認すると、アプリはあなたのアカウント専用のトークンを受け取ります。GitHub のパスワードをアプリに伝える必要はなく、アプリに秘密情報は組み込まれていません。\n\nトークンはこの端末のローカル設定にのみ保存されます。同期時、アプリは「ローカルバックアップ」と同じデータファイル（anikumo-backup.json）を、選択または自動作成したリポジトリに書き込みます。端末を変えたら、新しい端末で同じアカウントにログインし、同じリポジトリを選んで一度同期すればデータを復元できます。',
