  '四个专区怎么切换？': '4つのゾーンはどう切り替える？',
  '内容从哪里来？': 'コンテンツはどこから来るの？',
  '换手机后数据怎么搬？': '機種変更時のデータ移行は？',
  '弹幕没有 / 不准怎么办？': '弾幕がない／ずれる場合は？',
  '下载的视频 / 漫画在哪？': 'ダウンロードした動画と漫画はどこ？',
  '更新与公告': 'アップデートとお知らせ',
  '出问题了怎么反馈？': '不具合はどう報告する？',
  '点任意专区首页顶部的专区名标记（ANIME / 漫画 / 小说 / 影视），会拉起切换器。切换样式（上拉面板、滚轮、滑移、网格、分段）和专区顺序都可以在「设置 → 外观」里改。': '任意のゾーンホーム上部のゾーンマーク（ANIME／マンガ／小説／映画）をタップすると切替UIが開きます。切替スタイル（シート、ホイール、スライド、グリッド、セグメント）とゾーン順は「設定 → 外観」で変更できます。',
  'Anikumo 本身不提供内容。动漫与影视需要你自己添加内容源，漫画与小说需要安装书源 / 漫画源；影视区也可以在片源仓库里一键导入配置。没有源的时候，对应专区是空的，这是正常现象。': 'Anikumo 自体はコンテンツを提供しません。アニメと映画は自分でソースを追加し、マンガと小説はソースパックのインストールが必要です。映画ゾーンはリポジトリ設定の一括インポートも可能です。ソースがないゾーンは空になりますが正常です。',
  '两种方式：在「发现 → 本地备份与恢复」导出备份文件（可以加密），到新手机上导入；或者在「设置 → 同步」里配置 WebDAV，观看记录、收藏箱、三区收藏与进度都会同步，双边都改过同一区时会进冲突页让你选一份。': '2通りあります：「発見 → ローカルバックアップと復元」でバックアップファイル（暗号化可）を書き出して新しい端末で読み込む方法と、「設定 → 同期」で WebDAV を設定する方法です。履歴、コレクション、3ゾーンのお気に入りと進捗が同期され、両側で同じゾーンを変更した場合は競合ページでどちらか選びます。',
  '播放页的弹幕设置里可以手动搜索匹配；自动匹配走双线（官方线优先、备用线兜底）。发送的弹幕只保存在本机。也可以在弹幕设置里挂载本地弹幕文件（XML / JSON / ASS）。': 'プレイヤーの弾幕設定で手動検索できます。自動マッチは2回線（公式優先、予備がフォールバック）です。送信した弾幕はこの端末にのみ保存されます。ローカル弾幕ファイル（XML／JSON／ASS）も同じ設定から付けられます。',
  '动漫下载在「下载」页管理；漫画下载在漫画区的下载页，完整备份会把已下载的漫画章节一并打包。影视下载在影视区的下载中心，加密的 HLS 分片也会自动解密合并。': 'アニメのダウンロードは「ダウンロード」ページ、マンガはマンガゾーンのダウンロードページで管理します。フルバックアップにはダウンロード済み章も含まれます。映画は映画ゾーンのダウンロードセンターで、暗号化された HLS セグメントも自動で復号・結合されます。',
  'App 冷启动时会检查仓库里的公告，有新公告会弹窗一次。新版本在 GitHub 发布页与官网提供下载；发布说明会写清更新内容、优化与注意事项。': 'アプリは冷起動時にリポジトリのお知らせを確認し、新しいものを一度だけ表示します。新バージョンは GitHub リリースページと公式サイトで配布され、リリースノートには変更点、最適化、注意事項が必ず書かれます。',
  '先到「设置 → 日志」导出诊断包（日志尾段 + 已脱敏的设置摘要），再到 GitHub Issues 或官方 Discord 附上诊断包和复现步骤，这样定位最快。': 'まず「設定 → ログ」で診断パッケージ（ログ末尾＋秘匿済み設定サマリー）を書き出し、再現手順と一緒に GitHub Issues か公式 Discord に添付してください。それが最速の解決方法です。',
  '专区顺序': 'ゾーンの順序',
  '调整切换器里四个专区的排列顺序': 'スイッチャー内の4ゾーンの並び順を変更',
  '继续观看 · 全部专区': '続きから · 全ゾーン',
  '全部收藏': 'すべてのお気に入り',
